using Microsoft.AspNetCore.Mvc; using Mft.Application.Abstractions; using Mft.Application.Contracts; namespace Mft.Api.Controllers; [ApiController][Route("api/auth")] public sealed class AuthController(IAuthService auth):ControllerBase { [HttpPost("login")] public async Task<IActionResult> Login(LoginRequest r,CancellationToken ct){var x=await auth.LoginAsync(r,ct);return x is null?Unauthorized(new{message="نام کاربری یا رمز عبور صحیح نیست."}):Ok(x);} }